int32_t jestyr_parse_conv(Jestyr_Parser* restrict j_p)
{
    int32_t j_k = jestyr_cur_kind((*j_p));
    if ((j_k == 54))
    {
        jestyr_bump(&((*j_p)));
        return 1;
    }
    if ((j_k == 55))
    {
        jestyr_bump(&((*j_p)));
        return 2;
    }
    if ((j_k == 56))
    {
        jestyr_bump(&((*j_p)));
        return 3;
    }
    if ((j_k == 57))
    {
        jestyr_bump(&((*j_p)));
        return 4;
    }
    return 0;
}

