    jestyr_rt_str_push(&(*j_sb), JSTR("\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Jestyr string view — a length-carrying `{ptr, len}` (a borrowed UTF-8 view,\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("   like Zig `[]const u8` / Rust `&str`). `.len` is O(1); no `strlen`. A bare\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("   `cstr` (null-terminated `const char*`) is the distinct C-interop type. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("typedef struct { const char* ptr; size_t len; } JestyrStr;\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("#define JSTR(s) ((JestyrStr){ (s), sizeof(s) - 1 })\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* O(n) codepoint count (vs O(1) `.len`): a UTF-8 leading byte is one whose top two bits aren't 10. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static size_t jestyr_rt_count_cp(JestyrStr s) { size_t n = 0; for (size_t k = 0; k < s.len; k++) if (((uint8_t)s.ptr[k] & 0xC0u) != 0x80u) n++; return n; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Simplified grapheme segmentation: a cluster is a base codepoint plus following combining marks (é = e + U+0301). ZWJ emoji sequences are not merged — full UAX#29 needs Unicode tables. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_is_combining(uint32_t cp) { return (cp >= 0x0300u && cp <= 0x036Fu) || (cp >= 0x1AB0u && cp <= 0x1AFFu) || (cp >= 0x1DC0u && cp <= 0x1DFFu) || (cp >= 0x20D0u && cp <= 0x20FFu) || (cp >= 0xFE20u && cp <= 0xFE2Fu); }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Decode the UTF-8 codepoint at *k, advancing *k past it (replacement char on a bad lead byte). */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static uint32_t jestyr_rt_decode_cp(const char* p, size_t len, size_t* k) { size_t i = *k; uint8_t b = (uint8_t)p[i]; uint32_t cp; size_t n; if (b < 0x80u) { cp = b; n = 1; } else if ((b & 0xE0u) == 0xC0u) { cp = b & 0x1Fu; n = 2; } else if ((b & 0xF0u) == 0xE0u) { cp = b & 0x0Fu; n = 3; } else if ((b & 0xF8u) == 0xF0u) { cp = b & 0x07u; n = 4; } else { *k = i + 1; return 0xFFFDu; } for (size_t j = 1; j < n && i + j < len; j++) cp = (cp << 6) | ((uint8_t)p[i + j] & 0x3Fu); *k = i + n; return cp; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* O(n) grapheme-cluster count: base codepoints (combining marks attach to the preceding base). */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static size_t jestyr_rt_count_graphemes(JestyrStr s) { size_t k = 0, n = 0; while (k < s.len) { uint32_t cp = jestyr_rt_decode_cp(s.ptr, s.len, &k); if (!jestyr_rt_is_combining(cp)) n++; } return n; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Validate a byte range as UTF-8 (used at the bytes->str boundary). */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_valid_utf8(const char* p, size_t len) { size_t k = 0; while (k < len) { uint8_t b = (uint8_t)p[k]; size_t n; if (b < 0x80u) n = 1; else if ((b & 0xE0u) == 0xC0u) n = 2; else if ((b & 0xF0u) == 0xE0u) n = 3; else if ((b & 0xF8u) == 0xF0u) n = 4; else return false; if (k + n > len) return false; for (size_t j = 1; j < n; j++) if (((uint8_t)p[k + j] & 0xC0u) != 0x80u) return false; k += n; } return true; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* A boundary-checked sub-view (Rust discipline): start<=end<=len, and both on UTF-8 char boundaries. Zero-copy. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_is_boundary(JestyrStr s, size_t i) { return i == s.len || ((uint8_t)s.ptr[i] & 0xC0u) != 0x80u; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrStr jestyr_rt_substr(JestyrStr s, size_t start, size_t end) { assert(start <= end && end <= s.len); assert(jestyr_rt_is_boundary(s, start) && jestyr_rt_is_boundary(s, end)); return (JestyrStr){ s.ptr + start, end - start }; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Byte-level string operations: equality, prefix/suffix, search, trim. All view-based (find/trim are zero-copy). */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_str_eq(JestyrStr a, JestyrStr b) { return a.len == b.len && memcmp(a.ptr, b.ptr, a.len) == 0; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_starts_with(JestyrStr s, JestyrStr p) { return s.len >= p.len && memcmp(s.ptr, p.ptr, p.len) == 0; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_ends_with(JestyrStr s, JestyrStr p) { return s.len >= p.len && memcmp(s.ptr + (s.len - p.len), p.ptr, p.len) == 0; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static int64_t jestyr_rt_find(JestyrStr s, JestyrStr n) { if (n.len == 0) return 0; if (n.len > s.len) return -1; for (size_t i = 0; i + n.len <= s.len; i++) if (memcmp(s.ptr + i, n.ptr, n.len) == 0) return (int64_t)i; return -1; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_contains(JestyrStr s, JestyrStr n) { return jestyr_rt_find(s, n) >= 0; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrStr jestyr_rt_trim(JestyrStr s) { size_t a = 0, b = s.len; while (a < b) { char c = s.ptr[a]; if (c==' '||c=='\\t'||c=='\\n'||c=='\\r') a++; else break; } while (b > a) { char c = s.ptr[b-1]; if (c==' '||c=='\\t'||c=='\\n'||c=='\\r') b--; else break; } return (JestyrStr){ s.ptr + a, b - a }; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* ASCII case-insensitive equality — the opt-in normalization-aware compare. Full Unicode case-folding / NFC normalization needs the Unicode tables (deferred). */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static char jestyr_rt_ascii_lower(char c) { return (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_eq_fold(JestyrStr a, JestyrStr b) { if (a.len != b.len) return false; for (size_t i = 0; i < a.len; i++) if (jestyr_rt_ascii_lower(a.ptr[i]) != jestyr_rt_ascii_lower(b.ptr[i])) return false; return true; }\n\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Jestyr owned String — a heap-owned, growable buffer (the owned half of the\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("   owned/view split). `string_view` borrows it as a `str` view; no copy. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("typedef struct { char* ptr; size_t len; size_t cap; } JestyrString;\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrString jestyr_rt_str_new(void) { JestyrString s; s.ptr = NULL; s.len = 0; s.cap = 0; return s; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrString jestyr_rt_str_from(JestyrStr v) { JestyrString s; s.cap = v.len ? v.len : 1; s.ptr = (char*)malloc(s.cap); memcpy(s.ptr, v.ptr, v.len); s.len = v.len; return s; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static void jestyr_rt_str_push(JestyrString* s, JestyrStr v) { if (s->len + v.len > s->cap) { size_t nc = s->cap ? s->cap * 2 : 8; while (nc < s->len + v.len) nc *= 2; s->ptr = (char*)realloc(s->ptr, nc); s->cap = nc; } memcpy(s->ptr + s->len, v.ptr, v.len); s->len += v.len; }\n"));
