    jestyr_rt_str_push(&(*j_sb), JSTR("/* Append an integer's decimal digits (for f-string interpolation; copies). */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static void jestyr_rt_str_push_i64(JestyrString* s, int64_t v) { char b[24]; int n = snprintf(b, sizeof(b), \"%lld\", (long long)v); if (n < 0) n = 0; jestyr_rt_str_push(s, (JestyrStr){ b, (size_t)n }); }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Lossily decode unvalidated platform text (os_str) into a proven UTF-8 String, replacing each ill-formed byte with U+FFFD. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Cow<str>: borrowed-or-owned, visible. cap==0 means borrowed (no allocation, free is a no-op); cap>0 means owned. cow_to_mut is the copy-on-write point. */\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("typedef struct { char* ptr; size_t len; size_t cap; } JestyrCow;\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrCow jestyr_rt_cow_borrow(JestyrStr v) { JestyrCow c; c.ptr = (char*)v.ptr; c.len = v.len; c.cap = 0; return c; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static bool jestyr_rt_cow_is_owned(JestyrCow c) { return c.cap > 0; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrStr jestyr_rt_cow_view(JestyrCow c) { return (JestyrStr){ c.ptr, c.len }; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrCow jestyr_rt_cow_to_mut(JestyrCow c) { if (c.cap > 0) return c; JestyrCow o; o.cap = c.len ? c.len : 1; o.ptr = (char*)malloc(o.cap); memcpy(o.ptr, c.ptr, c.len); o.len = c.len; return o; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static void jestyr_rt_cow_free(JestyrCow* c) { if (c->cap > 0) free(c->ptr); c->ptr = NULL; c->len = 0; c->cap = 0; }\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("static JestyrString jestyr_rt_to_str_lossy(JestyrStr os) { JestyrString out = jestyr_rt_str_new(); size_t k = 0; while (k < os.len) { uint8_t b = (uint8_t)os.ptr[k]; size_t n; bool ok = true; if (b < 0x80u) n = 1; else if ((b & 0xE0u) == 0xC0u) n = 2; else if ((b & 0xF0u) == 0xE0u) n = 3; else if ((b & 0xF8u) == 0xF0u) n = 4; else { ok = false; n = 1; } if (ok && k + n <= os.len) { for (size_t j = 1; j < n; j++) if (((uint8_t)os.ptr[k + j] & 0xC0u) != 0x80u) { ok = false; break; } } else if (n > 1) ok = false; if (ok) { jestyr_rt_str_push(&out, (JestyrStr){ os.ptr + k, n }); k += n; } else { jestyr_rt_str_push(&out, (JestyrStr){ \"\\xEF\\xBF\\xBD\", 3 }); k += 1; } } return out; }\n\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("/* Jestyr Builder — an iolist: a list of `str` *fragments* collected with no\n"));
    jestyr_rt_str_push(&(*j_sb), JSTR("   copying; `builder_build` sums the lengths, allocates once, and flattens in a\n"));
